class Solution {
public:
    string maximumTime(string time) {
        // Hour digits at positions 0 and 1
        if (time[0] == '?' && time[1] == '?') {
            time[0] = '2';
            time[1] = '3';
        } else if (time[0] == '?') {
            // h2 known: if <= 3 we can use 2, otherwise 1
            time[0] = (time[1] <= '3') ? '2' : '1';
        } else if (time[1] == '?') {
            // h1 known: if 2 then max 3, otherwise 9
            time[1] = (time[0] == '2') ? '3' : '9';
        }
        // Minute digits at positions 3 and 4
        if (time[3] == '?') time[3] = '5';
        if (time[4] == '?') time[4] = '9';
        return time;
    }
};
